const STORAGE = { favorites: "krypta-favorites-v1", language: "krypta-language-v1" };
const RANGE_DAYS = { 1: 1, 7: 7, 30: 30, 365: 365 };
const DEFAULT_FAVORITES = ["bitcoin", "ethereum", "solana", "dogecoin"];
const LIVE_PRODUCTS = { btc: "BTC-EUR", eth: "ETH-EUR", usdt: "USDT-EUR", sol: "SOL-EUR", xrp: "XRP-EUR", doge: "DOGE-EUR", ada: "ADA-EUR", avax: "AVAX-EUR", usdc: "USDC-EUR", ltc: "LTC-EUR", link: "LINK-EUR", dot: "DOT-EUR" };
const state = {
  markets: SEED_MARKETS.map((coin) => ({ ...coin, demo: true, history: makeHistory(coin.price, coin.change) })), globalData: null,
  favorites: readFavorites(), selectedId: "bitcoin", range: 1, mode: "line", filter: "all", search: "", language: readLanguage(), live: false, chartData: [], currentPage: "overview", marketFetchInFlight: false, lastMarketUpdate: 0, lastGlobalUpdate: 0, nextMarketAttempt: 0, liveSocket: null, socketRetry: 0, socketGeneration: 0, livePrice: null
};
const currency = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR", maximumFractionDigits: 2 });
const compactCurrency = new Intl.NumberFormat("de-DE", { style: "currency", currency: "EUR", notation: "compact", maximumFractionDigits: 2 });
const numberCompact = new Intl.NumberFormat("de-DE", { notation: "compact", maximumFractionDigits: 2 });
const $ = (selector, root = document) => root.querySelector(selector);

function readFavorites() {
  try {
    const stored = JSON.parse(localStorage.getItem(STORAGE.favorites));
    return Array.isArray(stored) ? stored : [...DEFAULT_FAVORITES];
  } catch { return [...DEFAULT_FAVORITES]; }
}

function readLanguage() {
  try { return localStorage.getItem(STORAGE.language) === "en" ? "en" : "de"; }
  catch { return "de"; }
}

function t(key) { return PAGE_TRANSLATIONS[state.language][key] || TRANSLATIONS[state.language][key] || PAGE_TRANSLATIONS.de[key] || TRANSLATIONS.de[key] || key; }

function makeHistory(price, change) {
  let previous = price / (1 + change / 100);
  const start = previous;
  const values = [];
  const count = 72;
  for (let index = 0; index < count; index += 1) {
    const progress = index / (count - 1);
    const drift = (price - start) / count;
    const wave = Math.sin(index * 0.79 + price) * price * 0.0035;
    const noise = Math.cos(index * 2.17 + price / 10) * price * 0.0018;
    previous = Math.max(0.00001, previous + drift + wave + noise);
    values.push({ time: Date.now() - (count - 1 - index) * 20 * 60 * 1000, value: previous, open: previous * (1 + Math.sin(index * 1.7) * 0.002), high: previous * 1.004, low: previous * 0.996, close: previous });
  }
  values[values.length - 1].value = price;
  values[values.length - 1].close = price;
  return values;
}

function formatPrice(value, digits) {
  if (!Number.isFinite(value)) return "—";
  const maximumFractionDigits = digits ?? (value < 0.01 ? 6 : value < 1 ? 4 : 2);
  return new Intl.NumberFormat(state.language === "de" ? "de-DE" : "en-IE", { style: "currency", currency: "EUR", minimumFractionDigits: 2, maximumFractionDigits }).format(value);
}

function formatChange(value) {
  const sign = value > 0 ? "+" : "";
  return `${sign}${new Intl.NumberFormat(state.language === "de" ? "de-DE" : "en-IE", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value)} %`;
}

function formatCompact(value, style = "currency") {
  const locale = state.language === "de" ? "de-DE" : "en-IE";
  if (style === "number") return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value);
  return new Intl.NumberFormat(locale, { style: "currency", currency: "EUR", notation: "compact", maximumFractionDigits: 1 }).format(value);
}

function coinById(id) { return state.markets.find((coin) => coin.id === id); }
function coinClass(symbol) { return `${symbol.toLowerCase()}-icon`; }

function applyTranslations() {
  document.documentElement.lang = state.language;
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    if (t(key) !== key) element.textContent = t(key);
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => { element.placeholder = t(element.dataset.i18nPlaceholder); });
  document.querySelectorAll("[data-i18n-aria]").forEach((element) => { element.setAttribute("aria-label", t(element.dataset.i18nAria)); });
  document.querySelectorAll("[data-i18n-title]").forEach((element) => { element.title = t(element.dataset.i18nTitle); });
  $("#languageSelect").value = state.language;
  $("#marketCount").textContent = state.markets.length;
  $("#chartPeriodLabel").textContent = periodLabel();
  renderAll();
  showPage(state.currentPage);
}

function periodLabel() {
  return t(({ 1: "periodDay", 7: "periodWeek", 30: "periodMonth", 365: "periodYear" })[state.range]);
}

function renderAll() {
  renderPulse();
  renderWatchlist();
  renderMarketTable();
  renderSelectedAsset();
  drawChart();
}

function renderPulse() {
  const totalCap = state.globalData?.market_cap?.eur;
  const totalVolume = state.globalData?.total_volume?.eur;
  const bitcoin = coinById("bitcoin");
  $("#globalCap").textContent = totalCap ? formatCompact(totalCap) : "—";
  $("#globalVolume").textContent = totalVolume ? formatCompact(totalVolume) : "—";
  const dominance = state.globalData?.market_cap_percentage?.btc;
  $("#btcDominance").textContent = dominance ? `${new Intl.NumberFormat(state.language === "de" ? "de-DE" : "en-IE", { maximumFractionDigits: 1 }).format(dominance)} %` : "—";
  const averageChange = state.markets.reduce((sum, coin) => sum + coin.change, 0) / state.markets.length;
  const change = $("#globalChange");
  change.textContent = state.globalData?.market_cap_change_percentage_24h_usd == null ? "—" : `${formatChange(state.globalData.market_cap_change_percentage_24h_usd)} ${t("marketChange")}`;
  change.classList.toggle("positive", averageChange >= 0);
  change.classList.toggle("negative", averageChange < 0);
  const pageMetrics = { "#pageGlobalCap": totalCap ? formatCompact(totalCap) : "—", "#pageGlobalVolume": totalVolume ? formatCompact(totalVolume) : "—", "#pageBtcDominance": dominance ? `${new Intl.NumberFormat(state.language === "de" ? "de-DE" : "en-IE", { maximumFractionDigits: 1 }).format(dominance)} %` : "—" };
  Object.entries(pageMetrics).forEach(([selector, value]) => { const element = $(selector); if (element) element.textContent = value; });
}

function renderSelectedAsset() {
  const coin = coinById(state.selectedId) || state.markets[0];
  if (!coin) return;
  const icon = $("#selectedCoinIcon");
  icon.textContent = coin.icon;
  icon.className = `asset-coin-icon ${coinClass(coin.symbol)}`;
  $("#chartTitle").textContent = coin.name;
  $("#chartSymbol").textContent = `${coin.symbol.toUpperCase()} / EUR`;
  $("#chartPrice").textContent = formatPrice(coin.price);
  const change = $("#chartChange");
  change.textContent = formatChange(coin.change);
  change.className = `price-change ${coin.change >= 0 ? "positive" : "negative"}`;
  const favoriteButton = $("#chartFavorite");
  const saved = state.favorites.includes(coin.id);
  favoriteButton.textContent = saved ? "★" : "☆";
  favoriteButton.classList.toggle("is-saved", saved);
  favoriteButton.setAttribute("aria-label", `${saved ? "Aus Watchlist entfernen" : "Zur Watchlist hinzufügen"}: ${coin.name}`);
}

function setChartStatus(status) {
  const host = $("#chartLiveStatus");
  if (!host) return;
  state.chartStatus = status;
  const labels = { connecting: t("streamConnecting"), waiting: t("streamWaiting"), live: t("streamLive"), offline: t("streamOffline"), unsupported: t("streamUnsupported") };
  host.className = `chart-live is-${status}`;
  host.title = labels[status];
  host.querySelector("span:last-child").textContent = labels[status];
}

function renderWatchlist() {
  const favorites = state.favorites.map(coinById).filter(Boolean).slice(0, 6);
  const host = $("#watchlistBody");
  if (favorites.length === 0) {
    host.innerHTML = `<div class="watch-empty"><span>☆</span><strong>${escapeHtml(t("noFavorites"))}</strong><small>${escapeHtml(t("addFavorites"))}</small></div>`;
    return;
  }
  host.innerHTML = favorites.map((coin) => `<div class="watchlist-item" data-select="${coin.id}" tabindex="0" role="button" aria-label="${escapeHtml(coin.name)} Chart anzeigen"><span class="watch-coin-icon ${coinClass(coin.symbol)}">${coin.icon}</span><span class="watch-coin-name"><strong>${escapeHtml(coin.name)}</strong><small>${coin.symbol.toUpperCase()}</small></span><span class="watch-coin-price"><strong>${formatPrice(coin.price)}</strong><small class="${coin.change >= 0 ? "positive" : "negative"}">${formatChange(coin.change)}</small></span></div>`).join("");
}

function filteredMarkets() {
  return state.markets.filter((coin) => {
    const searchMatch = `${coin.name} ${coin.symbol}`.toLowerCase().includes(state.search.toLowerCase());
    return searchMatch && (state.filter === "all" || state.favorites.includes(coin.id));
  });
}

function renderMarketTable() {
  const coins = filteredMarkets();
  const markup = coins.map((coin) => {
    const saved = state.favorites.includes(coin.id);
    const color = coin.change >= 0 ? "#a7ec61" : "#ff827b";
    return `<tr data-select="${coin.id}" class="${state.selectedId === coin.id ? "selected-row" : ""}" tabindex="0"><td><div class="coin-cell"><span class="coin-icon ${coinClass(coin.symbol)}">${coin.icon}</span><span class="coin-details"><strong>${escapeHtml(coin.name)}</strong><small>${coin.symbol.toUpperCase()}</small></span></div></td><td>${formatPrice(coin.price)}</td><td><span class="change-pill ${coin.change >= 0 ? "positive" : "negative"}">${formatChange(coin.change)}</span></td><td class="spark-cell"><canvas class="sparkline" data-id="${coin.id}" aria-label="${escapeHtml(coin.name)} 7-Tage-Trend"></canvas></td><td>${formatCompact(coin.cap)}</td><td><button class="table-star ${saved ? "saved" : ""}" data-favorite="${coin.id}" aria-label="${saved ? "Aus Favoriten entfernen" : "Zu Favoriten hinzufügen"}: ${escapeHtml(coin.name)}" title="${saved ? "Aus Favoriten entfernen" : "Zu Favoriten hinzufügen"}">${saved ? "★" : "☆"}</button></td></tr>`;
  }).join("");
  document.querySelectorAll("#marketRows, [data-market-rows]").forEach((body) => { body.innerHTML = markup; });
  document.querySelectorAll("#emptyState, [data-empty-state]").forEach((empty) => { empty.hidden = coins.length > 0; });
  document.querySelectorAll("#resultsLabel, [data-results-label]").forEach((label) => { label.textContent = t("marketsCount").replace("{count}", String(coins.length)); });
  document.querySelectorAll(".sparkline").forEach((canvas) => drawSparkline(canvas, coinById(canvas.dataset.id), colorFor(coinById(canvas.dataset.id))));
}

function colorFor(coin) { return coin.change >= 0 ? "#a7ec61" : "#ff827b"; }

function drawSparkline(canvas, coin, color) {
  if (!coin) return;
  const bounds = canvas.getBoundingClientRect();
  const scale = window.devicePixelRatio || 1;
  const width = Math.max(1, bounds.width);
  const height = Math.max(1, bounds.height);
  canvas.width = Math.round(width * scale);
  canvas.height = Math.round(height * scale);
  const context = canvas.getContext("2d");
  context.scale(scale, scale);
  const data = coin.history.slice(-32).map((point) => point.value);
  const min = Math.min(...data);
  const max = Math.max(...data);
  const span = max - min || 1;
  context.beginPath();
  data.forEach((value, index) => {
    const x = index / (data.length - 1) * width;
    const y = height - 2 - (value - min) / span * (height - 5);
    if (index === 0) context.moveTo(x, y); else context.lineTo(x, y);
  });
  context.strokeStyle = color;
  context.lineWidth = 1.5;
  context.lineJoin = "round";
  context.stroke();
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]);
}

function visibleChartData() {
  const coin = coinById(state.selectedId) || state.markets[0];
  const data = state.chartData.length && state.selectedId === state.chartDataCoin ? state.chartData : coin.history;
  const cutoff = Date.now() - RANGE_DAYS[state.range] * 86_400_000;
  return data.filter((point) => point.time >= cutoff);
}

function drawChart() {
  const canvas = $("#priceChart");
  if (!canvas || !canvas.getBoundingClientRect().width) return;
  const context = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();
  const ratio = window.devicePixelRatio || 1;
  canvas.width = Math.round(rect.width * ratio);
  canvas.height = Math.round(rect.height * ratio);
  context.setTransform(ratio, 0, 0, ratio, 0, 0);
  const width = rect.width;
  const height = rect.height;
  const data = visibleChartData();
  if (data.length < 2) return;
  const left = 8;
  const right = 65;
  const top = 13;
  const bottom = 24;
  const plotWidth = width - left - right;
  const plotHeight = height - top - bottom;
  const values = data.flatMap((point) => state.mode === "candle" ? [point.high, point.low] : [point.value]);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const padding = (max - min || Math.max(max, 1) * 0.03) * 0.14;
  const low = min - padding;
  const high = max + padding;
  const yFor = (value) => top + (high - value) / (high - low) * plotHeight;
  const xFor = (index) => left + index / (data.length - 1) * plotWidth;
  context.font = "9px DM Sans, sans-serif";
  context.textAlign = "right";
  for (let line = 0; line < 4; line += 1) {
    const y = top + plotHeight * line / 3;
    const value = high - (high - low) * line / 3;
    context.beginPath();
    context.setLineDash([3, 5]);
    context.strokeStyle = "#2a322c";
    context.lineWidth = 1;
    context.moveTo(left, y);
    context.lineTo(left + plotWidth, y);
    context.stroke();
    context.setLineDash([]);
    context.fillStyle = "#778177";
    context.fillText(shortPrice(value), width - 2, y + 3);
  }
  const stroke = colorFor(coinById(state.selectedId) || state.markets[0]);
  if (state.mode === "candle") {
    const step = plotWidth / data.length;
    const candleWidth = Math.max(2, Math.min(8, step * 0.53));
    data.forEach((point, index) => {
      const x = xFor(index);
      const rising = point.close >= point.open;
      const candleColor = rising ? "#a7ec61" : "#ff827b";
      const openY = yFor(point.open);
      const closeY = yFor(point.close);
      context.beginPath();
      context.strokeStyle = candleColor;
      context.lineWidth = 1;
      context.moveTo(x, yFor(point.high));
      context.lineTo(x, yFor(point.low));
      context.stroke();
      context.fillStyle = candleColor;
      context.fillRect(x - candleWidth / 2, Math.min(openY, closeY), candleWidth, Math.max(1, Math.abs(closeY - openY)));
    });
  } else {
    const gradient = context.createLinearGradient(0, top, 0, height - bottom);
    gradient.addColorStop(0, `${stroke}38`);
    gradient.addColorStop(1, `${stroke}00`);
    context.beginPath();
    data.forEach((point, index) => {
      const x = xFor(index);
      const y = yFor(point.value);
      if (index === 0) context.moveTo(x, y); else context.lineTo(x, y);
    });
    context.lineTo(xFor(data.length - 1), top + plotHeight);
    context.lineTo(xFor(0), top + plotHeight);
    context.closePath();
    context.fillStyle = gradient;
    context.fill();
    context.beginPath();
    data.forEach((point, index) => {
      const x = xFor(index);
      const y = yFor(point.value);
      if (index === 0) context.moveTo(x, y); else context.lineTo(x, y);
    });
    context.strokeStyle = stroke;
    context.lineWidth = 2;
    context.lineJoin = "round";
    context.stroke();
    const last = data[data.length - 1];
    context.beginPath();
    context.arc(xFor(data.length - 1), yFor(last.value), 3, 0, Math.PI * 2);
    context.fillStyle = stroke;
    context.fill();
  }
  context.textAlign = "left";
  context.fillStyle = "#778177";
  const labels = state.range === 1 ? ["00:00", "06:00", "12:00", "18:00"] : state.range === 7 ? ["7 T", "5 T", "3 T", "Heute"] : state.range === 30 ? ["30 T", "20 T", "10 T", "Heute"] : ["1 J", "9 M", "6 M", "3 M"];
  labels.forEach((label, index) => context.fillText(label, left + plotWidth * index / 3, height - 5));
  if (state.mode === "line") {
    const last = data[data.length - 1];
    const markerY = yFor(last.value);
    context.setLineDash([3, 4]);
    context.strokeStyle = `${stroke}9a`;
    context.beginPath();
    context.moveTo(left, markerY);
    context.lineTo(left + plotWidth, markerY);
    context.stroke();
    context.setLineDash([]);
  }
}

function shortPrice(value) {
  if (value >= 1000) return `${(value / 1000).toFixed(1)}k`;
  if (value >= 1) return value.toFixed(0);
  return value.toPrecision(2);
}

function setFavorite(id) {
  if (state.favorites.includes(id)) {
    state.favorites = state.favorites.filter((favorite) => favorite !== id);
    showToast(`${coinById(id)?.name || id} ${t("removedWatch")}`);
  } else {
    state.favorites = [...state.favorites, id];
    showToast(`${coinById(id)?.name || id} ${t("addedWatch")}`);
  }
  try { localStorage.setItem(STORAGE.favorites, JSON.stringify(state.favorites)); } catch { /* Storage is optional in private browsing. */ }
  renderAll();
}

function showToast(message) {
  const toast = $("#toast");
  toast.textContent = message;
  toast.classList.add("is-visible");
  window.clearTimeout(showToast.timer);
  showToast.timer = window.setTimeout(() => toast.classList.remove("is-visible"), 2200);
}

function selectCoin(id) {
  if (!coinById(id)) return;
  if (state.currentPage !== "overview") navigateTo("overview");
  state.selectedId = id;
  state.chartData = [];
  state.chartDataCoin = id;
  renderAll();
  fetchChartData(id);
  connectLiveChart();
}

async function fetchMarkets() {
  if (state.marketFetchInFlight || Date.now() < state.nextMarketAttempt) return;
  state.marketFetchInFlight = true;
  state.nextMarketAttempt = Date.now() + 15_000;
  try {
    const response = await fetch("https://api.coingecko.com/api/v3/coins/markets?vs_currency=eur&order=market_cap_desc&per_page=10&page=1&sparkline=true&price_change_percentage=24h", { headers: { accept: "application/json" } });
    if (!response.ok) throw new Error(`Markt-API: ${response.status}`);
    const incoming = await response.json();
    if (!Array.isArray(incoming) || !incoming.length) throw new Error("Leere Marktantwort");
    state.markets = incoming.map((market) => {
      const previous = coinById(market.id);
      const prices = market.sparkline_in_7d?.price || [];
      const history = prices.map((value, index) => ({ time: Date.now() - (prices.length - 1 - index) * 30 * 60 * 1000, value, open: value * (1 + Math.sin(index * 2) * 0.0018), high: value * 1.004, low: value * 0.996, close: value }));
      if (history.length) { history[history.length - 1].value = market.current_price; history[history.length - 1].close = market.current_price; }
      return { id: market.id, symbol: market.symbol, name: market.name, price: market.current_price, change: market.price_change_percentage_24h || 0, cap: market.market_cap || 0, volume: market.total_volume || 0, icon: previous?.icon || symbolGlyph(market.symbol), history: history.length ? history : makeHistory(market.current_price, market.price_change_percentage_24h || 0), demo: false };
    });
    if (Date.now() - state.lastGlobalUpdate >= 60_000) try {
      const globalResponse = await fetch("https://api.coingecko.com/api/v3/global", { headers: { accept: "application/json" } });
      if (globalResponse.ok) {
        const globalResult = await globalResponse.json();
        state.globalData = globalResult.data || null;
        state.lastGlobalUpdate = Date.now();
      }
    } catch { state.globalData = null; }
    state.live = true;
    state.lastMarketUpdate = Date.now();
    const updated = new Intl.DateTimeFormat(state.language === "de" ? "de-DE" : "en-IE", { hour: "2-digit", minute: "2-digit" }).format(new Date());
    $("#updateLabel").textContent = t("apiLive").replace("{time}", updated);
    $("#chartSource").textContent = t("chartLive");
    $("#liveDot").style.background = "var(--green)";
    if (!coinById(state.selectedId)) state.selectedId = state.markets[0].id;
    renderAll();
  } catch {
    state.nextMarketAttempt = Date.now() + 30_000;
    if (!state.live) {
      $("#updateLabel").textContent = t("fallback");
      $("#chartSource").textContent = t("chartDemo");
      $("#liveDot").style.background = "var(--amber)";
    }
    renderAll();
  } finally {
    state.marketFetchInFlight = false;
  }
}

function symbolGlyph(symbol) {
  return ({ btc: "₿", eth: "◆", usdt: "₮", bnb: "◆", sol: "◎", xrp: "✕", usdc: "$", ada: "●", doge: "Ð", avax: "▲" })[symbol.toLowerCase()] || symbol.slice(0, 1).toUpperCase();
}

async function fetchChartData(id) {
  const coin = coinById(id);
  if (!coin) return;
  const requestId = `${id}:${state.range}:${state.mode}`;
  state.chartRequest = requestId;
  $("#refreshChartButton").classList.add("is-loading");
  $("#refreshChartButton").disabled = true;
  $("#chartLoading").hidden = false;
  try {
    const productId = LIVE_PRODUCTS[coin.symbol.toLowerCase()];
    if (productId) {
      try {
        const granularity = ({ 1: 300, 7: 3600, 30: 21600, 365: 86400 })[state.range];
        const response = await fetch(`https://api.exchange.coinbase.com/products/${productId}/candles?granularity=${granularity}`, { headers: { accept: "application/json" } });
        if (!response.ok) throw new Error(`Coinbase-Chart: ${response.status}`);
        const candles = await response.json();
        if (state.chartRequest !== requestId) return;
        if (!Array.isArray(candles) || !candles.length) throw new Error("Coinbase lieferte keine Kerzen");
        const cutoff = Date.now() - RANGE_DAYS[state.range] * 86_400_000;
        state.chartData = candles
          .map(([time, low, high, open, close]) => ({ time: time * 1000, open, high, low, close, value: close }))
          .filter((point) => point.time >= cutoff)
          .sort((first, second) => first.time - second.time);
        state.chartDataCoin = id;
        state.lastChartUpdate = Date.now();
        $("#chartSource").textContent = state.livePrice?.coinId === id ? t("chartLiveSource") : t("chartHistorySource");
        drawChart();
        return;
      } catch (error) {
        if (state.chartRequest !== requestId) return;
      }
    }
    const endpoint = state.mode === "candle" ? "ohlc" : "market_chart";
    const response = await fetch(`https://api.coingecko.com/api/v3/coins/${encodeURIComponent(id)}/${endpoint}?vs_currency=eur&days=${RANGE_DAYS[state.range]}`);
    if (!response.ok) throw new Error(`Chart-API: ${response.status}`);
    const data = await response.json();
    if (state.chartRequest !== requestId || !Array.isArray(state.mode === "candle" ? data : data.prices)) return;
    if (state.mode === "candle") {
      state.chartData = data.map(([time, open, high, low, close]) => ({ time, open, high, low, close, value: close }));
      state.chartDataCoin = id;
      state.lastChartUpdate = Date.now();
      $("#chartSource").textContent = t("chartLive");
      drawChart();
      return;
    }
    const prices = data.prices;
    const limit = 180;
    const stride = Math.max(1, Math.floor(prices.length / limit));
    const sampled = prices.filter((_, index) => index % stride === 0);
    state.chartData = sampled.map(([time, value], index) => {
      const previous = sampled[Math.max(0, index - 1)]?.[1] ?? value;
      const open = previous;
      return { time, value, open, close: value, high: Math.max(open, value) * 1.002, low: Math.min(open, value) * 0.998 };
    });
    state.chartDataCoin = id;
    state.lastChartUpdate = Date.now();
    $("#chartSource").textContent = t("chartLive");
    drawChart();
  } catch {
    if (state.chartRequest === requestId) {
      if (!state.chartData.length || state.chartDataCoin !== id) {
        state.chartData = [];
        state.chartDataCoin = id;
      }
      $("#chartSource").textContent = state.livePrice?.coinId === id ? t("chartLiveSource") : t("chartDemo");
      drawChart();
    }
  } finally {
    if (state.chartRequest === requestId) {
      $("#chartLoading").hidden = true;
      $("#refreshChartButton").classList.remove("is-loading");
      $("#refreshChartButton").disabled = false;
    }
  }
}

function connectLiveChart() {
  const coin = coinById(state.selectedId);
  if (!coin) return;
  const productId = LIVE_PRODUCTS[coin.symbol.toLowerCase()];
  state.socketGeneration += 1;
  const generation = state.socketGeneration;
  if (state.liveSocket) {
    state.liveSocket.onclose = null;
    state.liveSocket.close();
    state.liveSocket = null;
  }
  window.clearTimeout(state.socketRetryTimer);
  state.livePrice = null;
  state.socketUnsupported = false;
  if (!productId || !("WebSocket" in window)) {
    state.socketUnsupported = true;
    setChartStatus("unsupported");
    return;
  }
  setChartStatus("connecting");
  try {
    const socket = new WebSocket("wss://ws-feed.exchange.coinbase.com");
    state.liveSocket = socket;
    socket.addEventListener("open", () => {
      if (generation !== state.socketGeneration) return;
      state.socketRetry = 0;
      setChartStatus("waiting");
      socket.send(JSON.stringify({ type: "subscribe", product_ids: [productId], channels: ["ticker"] }));
    });
    socket.addEventListener("message", (event) => {
      if (generation !== state.socketGeneration) return;
      let message;
      try { message = JSON.parse(event.data); } catch { return; }
      if (message.type === "ticker" && message.product_id === productId) applyLiveTick(coin.id, Number(message.price), message);
      if (message.type === "error") {
        state.socketUnsupported = true;
        setChartStatus("unsupported");
        socket.close();
      }
    });
    socket.addEventListener("error", () => { if (generation === state.socketGeneration) setChartStatus("offline"); });
    socket.addEventListener("close", () => {
      if (generation !== state.socketGeneration) return;
      state.liveSocket = null;
      setChartStatus(state.socketUnsupported ? "unsupported" : "offline");
      if (!state.socketUnsupported && document.visibilityState !== "hidden") {
        const delay = Math.min(30_000, 2_000 * (2 ** state.socketRetry));
        state.socketRetry = Math.min(state.socketRetry + 1, 4);
        state.socketRetryTimer = window.setTimeout(() => { if (state.selectedId === coin.id) connectLiveChart(); }, delay);
      }
    });
  } catch {
    setChartStatus("offline");
  }
}

function applyLiveTick(coinId, price, message) {
  if (!Number.isFinite(price) || price <= 0) return;
  const coin = coinById(coinId);
  if (!coin) return;
  const now = message.time ? new Date(message.time).getTime() : Date.now();
  coin.price = price;
  const open24h = Number(message.open_24h);
  if (Number.isFinite(open24h) && open24h > 0) coin.change = (price / open24h - 1) * 100;
  state.livePrice = { coinId, price, time: now };
  if (state.chartDataCoin !== coinId || !state.chartData.length) {
    state.chartData = coin.demo ? [{ time: now, value: price, open: price, close: price, high: price, low: price }] : coin.history.map((point) => ({ ...point }));
    state.chartDataCoin = coinId;
  }
  if (state.chartDataCoin === coinId && state.chartData.length) {
    const series = state.chartData;
    const last = series[series.length - 1];
    if (state.mode === "candle") {
      const bucketMs = ({ 1: 5, 7: 60, 30: 240, 365: 1440 }[state.range]) * 60_000;
      const bucketTime = Math.floor(now / bucketMs) * bucketMs;
      if (last.time >= bucketTime) {
        last.close = price;
        last.value = price;
        last.high = Math.max(last.high, price);
        last.low = Math.min(last.low, price);
      } else {
        series.push({ time: bucketTime, open: price, high: price, low: price, close: price, value: price });
      }
    } else if (now - last.time >= 2_000) {
      series.push({ time: now, value: price, open: last.value, close: price, high: Math.max(last.value, price), low: Math.min(last.value, price) });
    } else {
      last.value = price;
      last.close = price;
      last.high = Math.max(last.high, price);
      last.low = Math.min(last.low, price);
    }
    if (series.length > 600) series.splice(0, series.length - 600);
    window.cancelAnimationFrame(state.chartFrame);
    state.chartFrame = window.requestAnimationFrame(drawChart);
  }
  setChartStatus("live");
  $("#chartSource").textContent = t("chartLiveSource");
  if (!state.liveRenderTimer) state.liveRenderTimer = window.setTimeout(() => {
    state.liveRenderTimer = null;
    renderAll();
  }, 250);
}

function initializeInteractions() {
  document.addEventListener("click", (event) => {
    const route = event.target.closest("[data-view]");
    if (!route) return;
    event.preventDefault();
    navigateTo(route.dataset.view);
  });
  window.addEventListener("hashchange", () => showPage(location.hash.replace(/^#\/?/, "") || "overview"));
  showPage(location.hash.replace(/^#\/?/, "") || "overview");
  $("#searchInput").addEventListener("input", (event) => {
    state.search = event.target.value.trim();
    if (state.search && state.currentPage !== "markets") navigateTo("markets");
    renderMarketTable();
  });
  $("#languageSelect").addEventListener("change", (event) => {
    state.language = event.target.value;
    try { localStorage.setItem(STORAGE.language, state.language); } catch { /* Language choice remains active for this tab. */ }
    applyTranslations();
    if (state.chartStatus) setChartStatus(state.chartStatus);
    if (state.live) fetchMarkets();
  });
  document.querySelectorAll(".range-button").forEach((button) => button.addEventListener("click", () => {
    state.range = Number(button.dataset.range);
    document.querySelectorAll(".range-button").forEach((item) => item.classList.toggle("active", item === button));
    $("#chartPeriodLabel").textContent = periodLabel();
    state.chartData = [];
    drawChart();
    fetchChartData(state.selectedId);
  }));
  document.querySelectorAll(".chart-mode").forEach((button) => button.addEventListener("click", () => {
    state.mode = button.dataset.mode;
    document.querySelectorAll(".chart-mode").forEach((item) => item.classList.toggle("active", item === button));
    state.chartData = [];
    drawChart();
    fetchChartData(state.selectedId);
  }));
  $("#refreshChartButton").addEventListener("click", () => fetchChartData(state.selectedId));
  document.querySelectorAll(".filter-button").forEach((button) => button.addEventListener("click", () => {
    state.filter = button.dataset.filter;
    document.querySelectorAll(".filter-button").forEach((item) => item.classList.toggle("active", item.dataset.filter === state.filter));
    renderMarketTable();
  }));
  document.querySelectorAll("#marketRows, [data-market-rows]").forEach((body) => {
    body.addEventListener("click", (event) => {
      const favoriteButton = event.target.closest("[data-favorite]");
      if (favoriteButton) { event.stopPropagation(); setFavorite(favoriteButton.dataset.favorite); return; }
      const row = event.target.closest("[data-select]");
      if (row) selectCoin(row.dataset.select);
    });
    body.addEventListener("keydown", (event) => {
      if ((event.key === "Enter" || event.key === " ") && event.target.matches("tr[data-select]")) { event.preventDefault(); selectCoin(event.target.dataset.select); }
    });
  });
  $("#watchlistBody").addEventListener("click", (event) => {
    const item = event.target.closest("[data-select]");
    if (item) selectCoin(item.dataset.select);
  });
  $("#watchlistBody").addEventListener("keydown", (event) => {
    if ((event.key === "Enter" || event.key === " ") && event.target.matches("[data-select]")) { event.preventDefault(); selectCoin(event.target.dataset.select); }
  });
  $("#chartFavorite").addEventListener("click", () => setFavorite(state.selectedId));
  $("#showAllMarkets").addEventListener("click", () => navigateTo("markets"));
  $("#addToWatchlist").addEventListener("click", () => {
    if (!state.favorites.includes(state.selectedId)) { setFavorite(state.selectedId); return; }
    const nextCoin = state.markets.find((coin) => !state.favorites.includes(coin.id));
    if (nextCoin) setFavorite(nextCoin.id); else showToast(t("noFavorites"));
  });
  document.querySelectorAll("#refreshButton, [data-refresh]").forEach((button) => button.addEventListener("click", () => {
    button.classList.add("is-loading");
    fetchMarkets().finally(() => window.setTimeout(() => button.classList.remove("is-loading"), 400));
  }));
  const dialog = $("#loginDialog");
  $("#loginButton").addEventListener("click", () => dialog.showModal());
  $("#loginButtonSide").addEventListener("click", () => dialog.showModal());
  $("#loginForm").addEventListener("submit", (event) => {
    event.preventDefault();
    const message = $("#loginMessage");
    message.textContent = t("demoMessage");
    message.hidden = false;
  });
  const canvas = $("#priceChart");
  canvas.addEventListener("pointermove", (event) => {
    const rect = canvas.getBoundingClientRect();
    const plotLeft = 8;
    const plotWidth = rect.width - 73;
    const data = visibleChartData();
    const index = Math.max(0, Math.min(data.length - 1, Math.round((event.clientX - rect.left - plotLeft) / plotWidth * (data.length - 1))));
    const point = data[index];
    if (!point) return;
    const tooltip = $("#chartTooltip");
    const date = new Intl.DateTimeFormat(state.language === "de" ? "de-DE" : "en-IE", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(point.time));
    const price = state.mode === "candle" ? point.close : point.value;
    tooltip.textContent = `${date} · ${formatPrice(price)}`;
    tooltip.hidden = false;
    const left = Math.max(5, Math.min(rect.width - tooltip.offsetWidth - 5, event.clientX - rect.left + 12));
    tooltip.style.left = `${left}px`;
  });
  canvas.addEventListener("pointerleave", () => { $("#chartTooltip").hidden = true; });
  window.addEventListener("resize", () => { drawChart(); document.querySelectorAll(".sparkline").forEach((spark) => drawSparkline(spark, coinById(spark.dataset.id), colorFor(coinById(spark.dataset.id)))); });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && !state.liveSocket && !state.socketUnsupported) connectLiveChart();
  });
  window.addEventListener("keydown", (event) => {
    if (event.key === "/" && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) { event.preventDefault(); $("#searchInput").focus(); }
  });
}

function navigateTo(page) {
  const validPages = ["overview", "markets", "strategies", "news", "learn", "brokers"];
  const nextPage = validPages.includes(page) ? page : "overview";
  if (location.hash !== `#/${nextPage}`) location.hash = `/${nextPage}`;
  showPage(nextPage);
}

function showPage(page) {
  const validPages = ["overview", "markets", "strategies", "news", "learn", "brokers"];
  const nextPage = validPages.includes(page) ? page : "overview";
  state.currentPage = nextPage;
  document.querySelectorAll(".page-view").forEach((view) => view.classList.toggle("active", view.dataset.page === nextPage));
  document.querySelectorAll(".nav-link[data-view]").forEach((link) => {
    const active = link.dataset.view === nextPage;
    link.classList.toggle("active", active);
    if (active) link.setAttribute("aria-current", "page"); else link.removeAttribute("aria-current");
  });
  const label = $("#currentPageLabel");
  const link = $(`.nav-link[data-view="${nextPage}"]`);
  if (label && link) label.textContent = link.querySelector("[data-i18n]")?.textContent || link.textContent.trim();
  if (nextPage === "markets") renderMarketTable();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function startAutoRefresh() {
  if (!state.lastMarketUpdate) state.lastMarketUpdate = Date.now();
  window.setInterval(() => {
    if (!state.marketFetchInFlight && Date.now() >= state.nextMarketAttempt) fetchMarkets();
    const age = Math.max(0, Math.floor((Date.now() - state.lastMarketUpdate) / 1000));
    const seconds = state.language === "de" ? `vor ${age} s aktualisiert` : `updated ${age}s ago`;
    const status = state.live ? `${state.language === "de" ? "Live-Kurse" : "Live prices"} · ${seconds}` : `${t("fallback")} · ${seconds}`;
    $("#updateLabel").textContent = status;
    document.querySelectorAll(".refresh-age").forEach((element) => { element.textContent = seconds; });
  }, 1000);
}

initializeInteractions();
applyTranslations();
fetchMarkets();
fetchChartData(state.selectedId);
connectLiveChart();
startAutoRefresh();
